{
  "version": 3,
  "sources": ["challan-check.component.ts"],
  "sourcesContent": ["\n    .check-challan-container {\n      max-width: 600px;\n      margin: 0 auto;\n    }\n\n    .back-link {\n      margin-bottom: 20px;\n    }\n\n    .back-link a {\n      color: #0066cc;\n      text-decoration: none;\n      font-size: 14px;\n    }\n\n    .check-card {\n      background: #fff;\n      border-radius: 12px;\n      padding: 32px;\n      box-shadow: 0 2px 8px rgba(0,0,0,0.08);\n    }\n\n    .check-card h1 {\n      font-size: 24px;\n      font-weight: 700;\n      color: #1a1a1a;\n      margin: 0 0 8px;\n    }\n\n    .subtitle {\n      color: #666;\n      margin: 0 0 24px;\n    }\n\n    .search-tabs {\n      display: flex;\n      gap: 8px;\n      margin-bottom: 24px;\n    }\n\n    .tab-btn {\n      flex: 1;\n      padding: 12px 16px;\n      border: 1px solid #e5e7eb;\n      background: #fff;\n      border-radius: 8px;\n      font-size: 14px;\n      cursor: pointer;\n      transition: all 0.2s;\n    }\n\n    .tab-btn:hover {\n      border-color: #0066cc;\n    }\n\n    .tab-btn.active {\n      background: #0066cc;\n      border-color: #0066cc;\n      color: #fff;\n    }\n\n    .form-group {\n      margin-bottom: 20px;\n    }\n\n    .form-group label {\n      display: block;\n      font-size: 14px;\n      font-weight: 500;\n      color: #333;\n      margin-bottom: 8px;\n    }\n\n    .form-control {\n      width: 100%;\n      padding: 14px 16px;\n      border: 1px solid #e5e7eb;\n      border-radius: 8px;\n      font-size: 16px;\n      text-transform: uppercase;\n    }\n\n    .form-control:focus {\n      outline: none;\n      border-color: #0066cc;\n      box-shadow: 0 0 0 3px rgba(0, 102, 204, 0.1);\n    }\n\n    .error {\n      color: #dc3545;\n      font-size: 13px;\n      margin-top: 6px;\n    }\n\n    .btn-primary {\n      padding: 14px 24px;\n      background: #0066cc;\n      color: #fff;\n      border: none;\n      border-radius: 8px;\n      font-weight: 500;\n      font-size: 16px;\n      cursor: pointer;\n    }\n\n    .btn-primary:disabled {\n      opacity: 0.6;\n      cursor: not-allowed;\n    }\n\n    .full-width {\n      width: 100%;\n    }\n\n    .error-message {\n      margin-top: 20px;\n      padding: 16px;\n      background: #fee2e2;\n      border-radius: 8px;\n      color: #991b1b;\n      text-align: center;\n    }\n\n    .no-results {\n      margin-top: 32px;\n      text-align: center;\n      padding: 32px 20px;\n      background: #d1fae5;\n      border-radius: 12px;\n    }\n\n    .success-icon {\n      width: 60px;\n      height: 60px;\n      background: #065f46;\n      color: #fff;\n      border-radius: 50%;\n      font-size: 32px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      margin: 0 auto 16px;\n    }\n\n    .no-results h3 {\n      font-size: 20px;\n      color: #065f46;\n      margin: 0 0 8px;\n    }\n\n    .no-results p {\n      color: #047857;\n      margin: 0;\n    }\n\n    .results-section {\n      margin-top: 32px;\n    }\n\n    .results-section h2 {\n      font-size: 18px;\n      font-weight: 600;\n      color: #1a1a1a;\n      margin: 0 0 16px;\n    }\n\n    .result-card {\n      border: 1px solid #e5e7eb;\n      border-radius: 10px;\n      margin-bottom: 12px;\n      overflow: hidden;\n    }\n\n    .result-header {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      padding: 12px 16px;\n      background: #f9fafb;\n      border-bottom: 1px solid #e5e7eb;\n    }\n\n    .challan-number {\n      font-weight: 600;\n      color: #1a1a1a;\n    }\n\n    .fine-amount {\n      font-weight: 700;\n      color: #dc3545;\n    }\n\n    .result-body {\n      padding: 16px;\n    }\n\n    .detail-row {\n      display: flex;\n      justify-content: space-between;\n      font-size: 14px;\n      padding: 6px 0;\n    }\n\n    .detail-row span:first-child {\n      color: #666;\n    }\n\n    .detail-row span:last-child {\n      color: #1a1a1a;\n    }\n\n    .result-footer {\n      padding: 12px 16px;\n      border-top: 1px solid #e5e7eb;\n      text-align: right;\n    }\n\n    .result-footer .btn-primary {\n      padding: 8px 20px;\n      font-size: 14px;\n    }\n\n    .total-section {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      padding: 20px;\n      background: #f9fafb;\n      border-radius: 10px;\n      margin: 20px 0;\n    }\n\n    .total-section span {\n      font-size: 16px;\n      color: #666;\n    }\n\n    .total-section strong {\n      font-size: 24px;\n      color: #1a1a1a;\n    }\n  "],
